/**
 * dsh-conversation-recorder —— 记录根下的产物文档（`<root>/README.md` 与 `<root>/AGENTS.md`）。
 *
 * 为什么需要：`_conversations` 这类记录目录常被当成「素材源」交给别的 agent 或人读，
 * 但一个只装 `session-<id>/` 目录的根没有一句话说明「这是什么、怎么读、能不能改」。
 * 本模块在**首个内容轮次落盘之后**确保这两份说明存在。
 *
 * 铁规矩（SPEC §10）：
 *   · **只缺则写**：文件已存在就**一律不动**（包括没有生成标记的手写文件——那种只往 stderr 提示一行，
 *     绝不改写、绝不覆盖）；故「手写内容被机器抹掉」这件事结构上不可能发生。
 *   · 新写出的文件首行是生成标记 `<!-- generated by dsh-conversation-recorder -->`，
 *     读者一眼能分辨「机器生成」与「人写的」。
 *   · `AGENTS.md` ≤ 2KB（写前按字节数检查，超了就当写失败处理，不落盘）。
 *   · 写失败（mkdir/写/rename 任一）只往 stderr 记一行，**不抛**、不影响记录主流程。
 *   · `enabled: false` 时**一个字节都不写**（总开关语义，SPEC §8）。
 *
 * 运行时依赖：仅 node 内置 + 同插件相对模块（SPEC §9）。
 */

import * as fs from 'node:fs'
import * as path from 'node:path'

/** 生成标记：新产出的文档首行（读者据此分辨机器生成与人写）。 */
export const DOC_GENERATED_MARKER = '<!-- generated by dsh-conversation-recorder -->'

/** 产物文档文件名（记录根下）。 */
export const DOC_FILES = ['README.md', 'AGENTS.md'] as const

/** `AGENTS.md` 的体积上限（字节）；`README.md` 不设上限（下文也远小于它）。 */
export const AGENTS_MAX_BYTES = 2048

/**
 * 记录根下的 `README.md`（面向**人**：这是什么、目录怎么排、能不能手改）。
 * 首行必须是生成标记。
 */
export function renderRootReadme(): string {
  return [
    DOC_GENERATED_MARKER,
    '# 会话记录（dsh-conversation-recorder 生成）',
    '',
    '本目录由 **dsh-conversation-recorder** 插件自动维护：DSH 每结束一个内容轮次，就把它落成一份可读的',
    'Markdown 记录，供人翻阅、也供其他 agent 当记忆读取。',
    '',
    '## 目录怎么排',
    '',
    '```',
    '<本目录>/',
    '└── <工作区文件夹>/          # 由会话的工作目录（cwd）转义而来',
    '    └── <sessionId>/        # 一个会话一个目录',
    '        ├── index.md        # 会话索引：frontmatter 元数据 + 轮次表',
    '        └── turns/',
    '            └── NNNN.md     # 逐轮正文（4 位零填充序号）',
    '```',
    '',
    '## 怎么读',
    '',
    '- 先看某个会话的 `index.md`：frontmatter 里有 `title` / `started` / `model` / `turns` / `fork_from`，',
    '  正文是 `| seq | time | kind |` 三列轮次表。',
    '- 再按需打开 `turns/NNNN.md`：frontmatter 的 `prev` 指向上一条记录，顺着它就能读完整条叙事链；',
    '  `## user` 是提问原文，`## assistant` 是回答正文，工具调用以清单行形式列在两者之间。',
    '- **序号只增不减**：`turns/` 里若缺了某个号（那一轮当年没落盘或后来被删），后续轮次**不会**回头占用它，',
    '  因此 `index.md` 的 `turns`（轮次个数）可能小于文件名里的最大序号——这是正常的。',
    '',
    '## 能不能手改',
    '',
    '- **不要手改**：本目录由插件写，手改会在下一次落盘时显得前后不一致。',
    '- 不要删 `turns/` 下的轮次文件：删掉留下的洞不会让序号回退，链会直接从更大的序号继续。',
    '- 不想要新记录：把插件的 `enabled` 设置关掉（已有内容不会被删）。',
    '',
    '本文件只在**缺失**时由插件写出；已存在就永不改写（包括你自己写的那份）。',
    '',
  ].join('\n')
}

/**
 * 记录根下的 `AGENTS.md`（面向**读这份记录的 AI agent**：最短的用法与红线）。
 * 首行必须是生成标记；正文必须 ≤ `AGENTS_MAX_BYTES` 字节。
 */
export function renderRootAgents(): string {
  return [
    DOC_GENERATED_MARKER,
    '# AGENTS.md —— 读这份会话记录时的约定',
    '',
    '本目录的 Markdown 由 **dsh-conversation-recorder** 插件自动生成。',
    '',
    '## 怎么读',
    '',
    '1. 找会话：`<工作区文件夹>/<sessionId>/index.md`。',
    '2. 读元数据：`index.md` 的 frontmatter（`title`/`started`/`model`/`turns`/`fork_from`）。',
    '3. 读某一轮：`turns/NNNN.md`；`## user` 提问、`## assistant` 回答、中间的工具清单行是调用摘要。',
    '4. 顺链读：`prev` 指向上一条记录；跨会话时形如 `../<父会话id>/turns/NNNN.md`（fork 血缘）。',
    '',
    '## 红线',
    '',
    '- **只读**：不要在本目录新建、改写、删除任何文件。',
    '- `turns/` 里缺号是正常的（序号只增不减，洞不回填）；`index.md` 的 `turns` 是**文件个数**，',
    '  有洞时它小于最大序号。',
    '- 不要把本目录的路径当成当前工作目录；记录是素材，不是待办或计划。',
    '- 想停掉后续记录：改插件的 `enabled` 设置，别删文件。',
    '',
  ].join('\n')
}

/** 往 stderr 记一行（写失败/提示都走这里，不抛给 DSH 事件总线）。 */
function warn(message: string): void {
  process.stderr.write(`dsh-conversation-recorder: ${message}\n`)
}

/**
 * 确保记录根下存在 `README.md` / `AGENTS.md`（**只缺则写**）。
 *
 * @param root - 记录根目录（`_conversations` 本身）；空串直接返回（没有落点可言）
 * @param options.handwrittenHint - 缺生成标记时是否往 stderr 提示一行（默认 true）
 * @returns 本次真正**新写出**的文件名（已存在的一律不算）
 */
export function ensureRootDocs(root: string, options: { readonly handwrittenHint?: boolean } = {}): string[] {
  const written: string[] = []
  if (root === '') return written
  const hint = options.handwrittenHint !== false
  const plan: readonly { readonly name: string; readonly body: () => string; readonly maxBytes?: number }[] = [
    { name: 'README.md', body: renderRootReadme },
    { name: 'AGENTS.md', body: renderRootAgents, maxBytes: AGENTS_MAX_BYTES },
  ]
  for (const file of plan) {
    const target = path.join(root, file.name)
    // ① 已存在：一律不动。没有生成标记的那种（人写的）额外提示一行——只提示，不改写。
    let existing: string | null = null
    try {
      existing = fs.readFileSync(target, 'utf8')
    } catch (error: unknown) {
      const code = (error as { code?: string }).code
      if (code !== 'ENOENT') {
        warn(`read ${target} failed: ${error instanceof Error ? error.message : String(error)}; 跳过（不覆盖）`)
        continue
      }
    }
    if (existing !== null) {
      if (hint && !existing.startsWith(DOC_GENERATED_MARKER)) {
        warn(`${target} 已存在且没有生成标记（手写文件），保持原样不动`)
      }
      continue
    }

    // ② 缺失：写出带生成标记的版本（体积超限就当写失败，不落盘）
    const body = file.body()
    const bytes = Buffer.byteLength(body, 'utf8')
    if (file.maxBytes !== undefined && bytes > file.maxBytes) {
      warn(`refuse write ${target}: ${String(bytes)} bytes > ${String(file.maxBytes)}`)
      continue
    }
    const tmp = target + '.tmp'
    try {
      fs.mkdirSync(root, { recursive: true })
      fs.writeFileSync(tmp, body, 'utf8')
      fs.renameSync(tmp, target)
      written.push(file.name)
    } catch (error: unknown) {
      warn(`write ${target} failed: ${error instanceof Error ? error.message : String(error)}`)
      try {
        fs.rmSync(tmp, { force: true })
      } catch {
        // 清理失败无所谓：已有 stderr 记录
      }
    }
  }
  return written
}
